-- =============================================================================
-- dbo.clientContactPreferences — marketing consent per client and channel
-- =============================================================================
-- Run manually against the live DB (no migration runner). Idempotent.
-- Deploy order: 1) this file  2) sql/sp_clientContactPreferences.sql
--               3) backend (modules/clientContactPreferences.py + whatsappCloud hook)
--
-- Generated by posgmo-factory (tests/prd_clientContactPreference.json), then
-- corrected by hand:
--   * UNIQUE (companyId, clientId, channel): one current preference per channel.
--     The generated table had none, and its "upsert" was a plain INSERT, so
--     every BAJA would have added a row.
--   * updatedByUserId has no FK: dbo.users has no primary key in the live DB
--     (error 1776 on any FK to it).
--   * CHECKs on channel and source.
-- Scope is MARKETING only (campaigns). Receipts and operational notices never
-- read this table. No row = unknown: whatsapp/sms not opted in, push opted in.
-- =============================================================================
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
GO

IF OBJECT_ID('dbo.clientContactPreferences', 'U') IS NULL
BEGIN
    CREATE TABLE [dbo].[clientContactPreferences] (
        [clientContactPreferenceId] INT IDENTITY(1,1) NOT NULL,
        [companyId]       INT          NOT NULL,
        [clientId]        INT          NOT NULL,
        [channel]         NVARCHAR(20) NOT NULL,
        [marketingOptIn]  BIT          NOT NULL,
        [source]          NVARCHAR(30) NOT NULL,
        [optedInAt]       DATETIME     NULL,   -- UTC
        [optedOutAt]      DATETIME     NULL,   -- UTC
        [updatedByUserId] INT          NULL,   -- no FK: dbo.users has no PK
        [active]          BIT          NOT NULL CONSTRAINT [DF_clientContactPreferences_active] DEFAULT 1,
        [created_At]      DATETIME     NOT NULL CONSTRAINT [DF_clientContactPreferences_created_At] DEFAULT GETDATE(),
        [updated_at]      DATETIME     NULL,
        CONSTRAINT [PK_clientContactPreferences] PRIMARY KEY CLUSTERED ([clientContactPreferenceId] ASC),
        CONSTRAINT [UQ_clientContactPreferences_company_client_channel] UNIQUE ([companyId], [clientId], [channel]),
        CONSTRAINT [CK_clientContactPreferences_channel] CHECK ([channel] IN (N'whatsapp', N'sms', N'push')),
        CONSTRAINT [CK_clientContactPreferences_source]
            CHECK ([source] IN (N'pos_checkout', N'client_app', N'whatsapp_keyword', N'admin')),
        CONSTRAINT [FK_clientContactPreferences_companies_companyId] FOREIGN KEY ([companyId]) REFERENCES [dbo].[companies]([companyId]),
        CONSTRAINT [FK_clientContactPreferences_clients_clientId] FOREIGN KEY ([clientId]) REFERENCES [dbo].[clients]([clientId])
    );
END
GO

IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE name = 'IX_clientContactPreferences_clientId'
               AND object_id = OBJECT_ID('dbo.clientContactPreferences'))
    CREATE NONCLUSTERED INDEX [IX_clientContactPreferences_clientId]
        ON [dbo].[clientContactPreferences] ([clientId]);
GO
